import{z as l,x as s,o as i,c as d,q as n,j as o,D as B,d as E,s as r,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"join 算法的实现","description":"","frontmatter":{"title":"join 算法的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/qo-join-implementation.md","filePath":"cs/qo-join-implementation.md","lastUpdated":1791413859000}'),D={name:"cs/qo-join-implementation.md"};function p(h,a,m,C,c,u){const A=s("Mermaid");return i(),d("div",null,[a[2]||(a[2]=n('<h1 id="join-算法的实现" tabindex="-1">join 算法的实现 <a class="header-anchor" href="#join-算法的实现" aria-label="Permalink to &quot;join 算法的实现&quot;">​</a></h1><div class="epigraph"><p>哈希连接的快慢不在算法名里，而在 build 侧落进哪级缓存、分区写几遍、探针白问几次。同一个「分区哈希」，常数可以差数倍。</p><footer>—— 据 Boncz, Manegold and Kersten, 1999；Graefe 查询执行综述整理</footer></div><p><a href="/cs/qo-cost-model">上一课</a>把算子代价封装成询价接口，也承认接口之下的常数由实现决定。主干把三种 I/O 形状与分区协议钉死在<a href="/cs/nlj-hash-join">嵌套循环与哈希连接</a>、<a href="/cs/grace-hash-join">Grace hash join</a> 与 <a href="/cs/hash-aggregation">hash-aggregation</a> 里。本课进入实现层：build 侧怎么选、分区对齐什么、倾斜怎么救——这些决定代价公式里那个「常数」到底是几。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代价模型说哈希连接便宜，实现决定它便宜多少。四件事。选边：build 侧应选估计较小的输入，还要选<strong>列窄</strong>的一侧——哈希表里只放连接键与行位置，载荷列留给之后按位置取，这是<a href="/cs/late-materialization">延迟物化</a>在连接里的用法。缓存：哈希表一旦超过末级缓存，每次探测都是一次随机内存访问，百纳秒起步，探测循环崩在访存而不是计算，SIMD 也救不了等内存。倾斜：高频键让某个分区仍然放不下，Grace 的「同键同分区」保证正确，不救单键倾斜。白做功：连接之后才过滤的谓词，让 build 侧白白收下本会被丢弃的行。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分区对齐缓存：把 build 输入按连接键高位切成 \\(P\\) 个分区，目标是每个分区的哈希表落进二级或末级缓存。基数分区（radix partitioning）分两阶段：先粗分区，用大块顺序写；再细分区，让探测阶段的随机访问停在缓存里。布隆预过滤：build 时把键插入布隆摘要，probe 侧每行先问布隆，必不命中的直接丢弃——省下的是整行拷贝与哈希表探测。假阳性率约 \\(0.6185^{m/n}\\)（取 \\(k=\\ln 2\\cdot m/n\\) 个哈希函数时），每键十个比特约百分之一：几十兆内存换掉大半无效探测。倾斜处理：先采样发现热键，把热键行单独拎出建子表，或对热键走专门分支；分区内递归再划分只救「分区仍大」，救不了「单键巨大」。</p>',7)),(i(),o(t,null,{default:B(()=>[r(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUILD%5B%22build%EF%BC%9A%E9%94%AE%E5%88%97%20%2B%20%E8%A1%8C%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20RADIX%5B%22radix%20%E5%88%86%E5%8C%BA%E5%AF%B9%E9%BD%90%E7%BC%93%E5%AD%98%22%5D%0A%20%20RADIX%20--%3E%20BLOOM%5B%22%E5%BB%BA%E5%B8%83%E9%9A%86%E6%91%98%E8%A6%81%22%5D%0A%20%20SKEW%5B%22%E7%83%AD%E9%94%AE%E5%8D%95%E7%8B%AC%E5%BB%BA%E5%AD%90%E8%A1%A8%22%5D%20--%3E%20BLOOM%0A%20%20PROBE%5B%22probe%20%E8%A1%8C%E5%85%88%E9%97%AE%E5%B8%83%E9%9A%86%22%5D%20--%3E%20MISS%5B%22%E4%B8%8D%E5%91%BD%E4%B8%AD%E5%8D%B3%E4%B8%A2%E5%BC%83%22%5D%0A%20%20PROBE%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%E5%86%8D%E6%9F%A5%E5%88%86%E5%8C%BA%E5%93%88%E5%B8%8C%E8%A1%A8%22%5D%0A%20%20HIT%20--%3E%20GATHER%5B%22%E6%8C%89%E4%BD%8D%E7%BD%AE%E5%8F%96%E8%BD%BD%E8%8D%B7%E5%88%97%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("分区为什么省时间：随机访问的代价由目标住在哪一级存储决定，寄存器、各级缓存、内存的延迟差一个量级一级；分区把随机性局部化，等于把「随机访问内存」换成「顺序写一遍加缓存内随机」。这与哈希聚合里「组能否驻留」的判断同源。"),e("span",{class:"marginnote"},"量级账：一级缓存约一纳秒，末级缓存约十纳秒，内存约百纳秒。分区把探测延迟从百纳秒档拉回个位纳秒档——布隆与 radix 分区买的就是这几档差价。"),E("向量化让键比较与布隆查询按批走向量指令，冲突链才退回标量。半连接与存在性检查在首个匹配处早停，不必枚举全部配对。列存路径上，探测产出位置向量，载荷列延后成批取回，顺序 gather 对缓冲池友好。")],-1)),a[5]||(a[5]=e("p",null,"代价模型的接口在这里兑现：实现者把「探测落进缓存」「布隆过滤率」「热键占比」翻译回 CPU 项与选择率，优化器才能在同构候选间比较——否则它只看见两个都叫 hash join 的黑盒。",-1)),(i(),o(t,null,{default:B(()=>[r(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20NP%5B%22%E4%B8%8D%E5%88%86%E5%8C%BA%EF%BC%9A%E5%93%88%E5%B8%8C%E8%A1%A8%E8%B6%85%E6%9C%AB%E7%BA%A7%E7%BC%93%E5%AD%98%22%5D%20--%3E%20RA%5B%22%E6%AF%8F%E6%AC%A1%E6%8E%A2%E6%B5%8B%20%3D%20%E4%B8%80%E6%AC%A1%E9%9A%8F%E6%9C%BA%E5%86%85%E5%AD%98%E8%AE%BF%E9%97%AE%22%5D%0A%20%20RA%20--%3E%20COST%5B%22%E5%BB%B6%E8%BF%9F%E7%BA%A6%E7%99%BE%E7%BA%B3%E7%A7%92%EF%BC%8C%E6%8E%A2%E6%B5%8B%E5%BE%AA%E7%8E%AF%E5%B4%A9%E5%9C%A8%E8%AE%BF%E5%AD%98%22%5D%0A%20%20P%5B%22%E5%88%86%E5%8C%BA%E5%90%8E%EF%BC%9A%E6%AF%8F%E5%88%86%E5%8C%BA%E5%93%88%E5%B8%8C%E8%A1%A8%E8%90%BD%E8%BF%9B%E7%BC%93%E5%AD%98%22%5D%20--%3E%20CR%5B%22%E9%9A%8F%E6%9C%BA%E8%AE%BF%E9%97%AE%E8%A2%AB%E5%B1%80%E9%83%A8%E5%8C%96%22%5D%0A%20%20CR%20--%3E%20FAST%5B%22%E9%A1%BA%E5%BA%8F%E5%86%99%E4%B8%80%E9%81%8D%20%2B%20%E7%BC%93%E5%AD%98%E5%86%85%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20NP%20-.-%3E%7C%22radix%20%E5%88%86%E5%8C%BA%E5%AF%B9%E9%BD%90%E7%BC%93%E5%AD%98%22%7C%20P%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比：布隆过滤器像个记性极差但绝不会冤枉人的门卫——它说「这人肯定没来过」就一定没来过（无假阴性），说「可能来过」时得再查名单核实（有假阳性）。所以 probe 行先问它，被拦下的行绝不冤枉，放行的行再查真正的哈希表。</span></p><p><span class="marginnote">数字实例：每键十个比特，一百万个键的布隆摘要就是一千万比特，约 1.25 MB 内存；换来的假阳性率约百分之一——也就是说九成以上的无效探测（probe 行根本不可能配上对）被这 1.25 MB 直接拦掉。</span></p><p><span class="marginnote">术语翻译：「延迟物化」在连接里的做法是——哈希表里只存连接键加行位置号，其余列先不搬；等连接结果定了，再按位置号成批去原表取载荷列。就像寄存行李先拿号码牌，出场上才凭牌取箱，避免把整只箱子一直背在身上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跨节点 shuffle 与网络归分布式课，本课单机；Grace 的正确性论证（同键同分区）主干已给，不重证。归并连接的实现要点（归并有序流、保序 exchange）在执行引擎课已展开，本课只以哈希为主线。选错 build 侧的灾难来自估计错——下一课统计信息接手。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>build 侧选小且窄：键列加行位置，载荷延迟取。</li><li>分区目标是对齐缓存；基数分区把探测留在末级缓存内。</li><li>布隆用比特换探测，每键十比特假阳性约百分之一。</li><li>热键单独处理；递归划分救分区不救单键。</li><li>出处：Boncz, Manegold and Kersten, 1999；Kitsuregawa 等；Graefe 综述。</li></ul>',7))])}const g=l(D,[["render",p]]);export{b as __pageData,g as default};
